/** Old (pre-v3.1) icon names that still work, mapped to their v3.1 equivalent. */
export const ICON_ALIASES = {
  path: "route",
  resources: "book",
  chat: "speech",
  profile: "user",
  "map-pin": "pin",
} as const satisfies Record<string, keyof typeof ICONS>;

export type IconName = keyof typeof ICONS | keyof typeof ICON_ALIASES;
export const ICON_NAMES = Object.keys(ICONS) as (keyof typeof ICONS)[];
export const resolveIcon = (name: IconName): keyof typeof ICONS =>
  name in ICON_ALIASES ? ICON_ALIASES[name as keyof typeof ICON_ALIASES] : (name as keyof typeof ICONS);
/** Icons that point in a reading direction and must mirror in right-to-left layouts. */
export const DIRECTIONAL_ICONS: ReadonlySet<keyof typeof ICONS> = new Set(["arrow-left", "arrow-right", "chevron-right", "external", "send"]);
